-- Source: FED_CFTC_COT_FINANCIAL_HIST (4615 rows)
-- Generated by scripts/gen_mart_models.py
-- Fixed 2026-09-20: AS_OF_DATE_IN_FORM_YYMMDD was a bare try_to_date() with NO
-- format at all -- live-confirmed ALL 4,615 of 4,615 rows (100%) silently
-- misparsed to 1970-01-0x, the epoch-seconds trap, because the 6-digit string
-- ('101228') was never given a format to parse against. Now guarded with an
-- inline regexp_like digit-count check plus the explicit 'YYMMDD' format --
-- stg_date's explicit-format branch hardcodes an 8-digit check and this field
-- is 6 digits, so the shared macro can't be called directly. Correctly reads
-- 2010-12-28 now instead of 1970-01-02. REPORT_DATE_AS_MM_DD_YYYY was also a
-- bare try_to_date() (live-checked clean today, dash-separated already) --
-- now goes through stg_date(col) (auto) for the same guard everywhere else.

with source as (
    select * from {{ source('ripple_raw', 'FED_CFTC_COT_FINANCIAL_HIST') }}
)

select
    MARKET_AND_EXCHANGE_NAMES as market_and_exchange_names,
    iff(regexp_like(trim(AS_OF_DATE_IN_FORM_YYMMDD), '[0-9]{6}'),
        try_to_date(trim(AS_OF_DATE_IN_FORM_YYMMDD), 'YYMMDD'), null) as as_of_date_in_form_yymmdd,
    {{ stg_date('REPORT_DATE_AS_MM_DD_YYYY') }} as report_date_as_mm_dd_yyyy,
    CFTC_CONTRACT_MARKET_CODE as cftc_contract_market_code,
    CFTC_MARKET_CODE as cftc_market_code,
    CFTC_REGION_CODE as cftc_region_code,
    CFTC_COMMODITY_CODE as cftc_commodity_code,
